package com.example.starter.marpol.domain;

/**
 * 排放记录类型。
 */
public enum RecordType {
    /** 油类：特殊区域内禁止排放。 */
    OIL,
    /** 垃圾：距最近陆地不得少于 12 海里。 */
    GARBAGE,
    /** 生活污水：特殊区域内禁止排放。 */
    SEWAGE
}

package com.example.starter.marpol.domain;

/**
 * 排放记录版本状态。
 */
public enum RecordVersionStatus {
    /** 最新有效版本（查询默认返回）。 */
    ACTIVE,
    /** 已被新版本取代，原版本保留可查。 */
    SUPERSEDED
}

package com.example.starter.marpol.domain;

/**
 * 航次状态。
 */
public enum VoyageStatus {
    /** 开放：允许新增排放记录。 */
    OPEN,
    /** 已关闭：关闭后新增记录一律拒绝。 */
    CLOSED
}

package com.example.starter.marpol.domain;

/**
 * 港口国核查状态。
 */
public enum InspectionState {
    /** 进行中：可逐条确认/标注，结论可改。 */
    OPEN,
    /** 已签发：终态，结论不可再改，只能走复查补充证据。 */
    ISSUED
}

package com.example.starter.marpol.domain;

/**
 * 核查条目结论。
 */
public enum Decision {
    /** 确认。 */
    CONFIRMED,
    /** 标注违规：立即生成缺陷项并限期整改。 */
    VIOLATION
}

package com.example.starter.marpol.domain;

/**
 * 缺陷项整改状态。
 */
public enum ItemStatus {
    /** 待整改：截止日（核查日+14 自然日，UTC）前可关闭。 */
    OPEN,
    /** 已按期整改关闭（恰第 14 日关闭仍有效）。 */
    RECTIFIED,
    /** 逾期未整改关闭。 */
    OVERDUE
}

package com.example.starter.marpol.error;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类，携带 HTTP 状态码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

package com.example.starter.marpol.error;

import org.springframework.http.HttpStatus;

/**
 * 409：幂等键冲突、并发版本冲突、终态核查被修改等。
 */
public class ConflictException extends ApiException {

    public ConflictException(String message) {
        super(HttpStatus.CONFLICT, message);
    }
}

package com.example.starter.marpol.error;

import org.springframework.http.HttpStatus;

/**
 * 404：船舶、航次、记录或核查不存在。
 */
public class NotFoundException extends ApiException {

    public NotFoundException(String message) {
        super(HttpStatus.NOT_FOUND, message);
    }
}

package com.example.starter.marpol.error;

import org.springframework.http.HttpStatus;

/**
 * 422：业务规则不满足，如特殊区域内排污、垃圾距陆地不足 12 海里、航次已关闭等。
 */
public class RuleViolationException extends ApiException {

    public RuleViolationException(String message) {
        super(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

package com.example.starter.marpol.support;

import org.springframework.stereotype.Component;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;

/**
 * 统一 UTC 时钟。生产使用系统 UTC 时钟；测试可替换为固定时钟以验证整改期限等时间口径。
 */
@Component
public class ServiceClock {

    private volatile Clock clock = Clock.systemUTC();

    public Instant now() {
        return Instant.now(clock);
    }

    /** UTC 日界下的当前日期。 */
    public LocalDate todayUtc() {
        return now().atOffset(ZoneOffset.UTC).toLocalDate();
    }

    /** 替换底层时钟（主要供测试使用）。 */
    public void setClock(Clock clock) {
        this.clock = clock;
    }

    /** 恢复系统 UTC 时钟。 */
    public void reset() {
        this.clock = Clock.systemUTC();
    }
}

