                "/api/inspections/" + inspectionNo + "/items/" + itemId + "/rectify", null);
        assertEquals(HttpStatus.OK, rectified.getStatusCode());
        assertEquals("RECTIFIED", rectified.getBody().path("itemStatus").asText());

