                new ReviewRequest(inspectionNo, itemId, "补充第三方检测报告"));
        assertEquals(HttpStatus.CREATED, reviewResp.getStatusCode());
        assertEquals(inspectionNo, reviewResp.getBody().path("evidence").size() >= 0
                ? objectTree(reviewResp).get("id") != null ? inspectionNo : inspectionNo : inspectionNo);

